"""Generate the native CLI's offline flag types from the Python registry."""

from __future__ import annotations

import json
import subprocess
import sys
from pathlib import Path

from r10n_backend.registry import list_automations

ROOT = Path(__file__).resolve().parents[1]
DESTINATION = ROOT / "internal/cli/flag_schema_generated.go"


def render() -> str:
    """Return Go source describing each automation's input field types."""
    lines = [
        "// Code generated by scripts/generate_flag_schema.py; DO NOT EDIT.",
        "package cli",
        "",
        "var flagFieldTypes = map[string]map[string]bool{",
    ]
    for spec in list_automations():
        properties = spec.input_model.model_json_schema()["properties"]
        fields = {}
        for name, field in properties.items():
            alternatives = field.get("anyOf", [field])
            scalar = next((item for item in alternatives if item.get("type") != "null"), field)
            fields[name] = scalar.get("type") == "boolean"
        if fields:
            lines.append(f"\t{json.dumps(spec.id)}: {{")
            lines.extend(
                f"\t\t{json.dumps(name)}: {str(fields[name]).lower()}," for name in sorted(fields)
            )
            lines.append("\t},")
    lines.extend(["}", ""])
    return subprocess.check_output(["gofmt"], input="\n".join(lines), text=True)


def main() -> int:
    """Write the generated schema, or check it with --check."""
    output = render()
    if sys.argv[1:] == ["--check"]:
        if not DESTINATION.exists() or DESTINATION.read_text(encoding="utf-8") != output:
            print(
                "Offline CLI flag schema is stale; run go generate ./internal/cli", file=sys.stderr
            )
            return 1
        return 0
    if sys.argv[1:]:
        print("Usage: generate_flag_schema.py [--check]", file=sys.stderr)
        return 2
    DESTINATION.write_text(output, encoding="utf-8")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
